'use client';
import { jsx as _jsx } from "react/jsx-runtime";
// 用到 React hook 或 Base UI 的模組標成 client 元件，Next App Router 的伺服器元件才能匯入套件入口（PR-ADOPT-01）。
import { Button as BaseButton } from '@base-ui/react/button';
import { useRender } from '@base-ui/react/use-render';
const classNameOf = (variant, className) => `luca-button luca-button-${variant} ${className}`.trim();
// 連結不經過 Base UI Button：Base UI 文件說 <a> 不該放進 Button 的 render，它會加上按鈕的 type 與鍵盤行為。改用 Base UI 的 useRender 渲染，保留連結語意。
function LinkButton({ className = '', variant = 'primary', render, ...props }) {
    return useRender({ render: render, defaultTagName: 'a', props: { ...props, className: classNameOf(variant, className) } });
}
export function Button(props) {
    if ('render' in props && props.render)
        return _jsx(LinkButton, { ...props });
    const { className = '', type = 'button', variant = 'primary', loading = false, disabled, ...rest } = props;
    // 以 Base UI 的 Button 處理互動；仍是原生 <button>，停用時不可聚焦（與 0.1.0 相同，不開 focusableWhenDisabled）。
    return _jsx(BaseButton, { ...rest, type: type, disabled: disabled || loading, "aria-busy": loading || undefined, "aria-disabled": loading || undefined, className: classNameOf(variant, className) });
}

