import type { AnchorHTMLAttributes, ButtonHTMLAttributes, ReactElement, Ref } from 'react';
type ButtonVariant = 'primary' | 'secondary';
export type ButtonProps = ButtonHTMLAttributes<HTMLButtonElement> & {
    variant?: ButtonVariant;
    loading?: boolean;
};
export type ButtonLinkRenderProps = AnchorHTMLAttributes<HTMLAnchorElement> & {
    ref?: Ref<HTMLAnchorElement>;
};
export type ButtonLinkProps = Omit<AnchorHTMLAttributes<HTMLAnchorElement>, 'type'> & {
    variant?: ButtonVariant;
    render: ReactElement | ((props: ButtonLinkRenderProps) => ReactElement);
    disabled?: never;
    loading?: never;
    type?: never;
};
export declare function Button(props: ButtonLinkProps): ReactElement;
export declare function Button(props: ButtonProps): ReactElement;
export {};
